int epoll_ctl(int epfd, int op, int fd, struct epoll_event __user *event) {
    struct file *file, *f;
    struct inode *inode;
    struct epoll *ep;
    int error;

    file = fget(epfd);
    if (!file)
        return -EBADF;

    inode = file->f_path.dentry->d_inode;
    if (!S_ISCHR(inode->i_mode)) {
        fput(file);
        return -EINVAL;
    }

    ep = inode->i_private;
    if (!ep) {
        fput(file);
        return -EINVAL;
    }

    mutex_lock(&ep->mtx);
    f = fget(fd);
    if (!f) {
        mutex_unlock(&ep->mtx);
        fput(file);
        return -EBADF;
    }

    if (f == file) {
        fput(f);
        fput(file);
        mutex_unlock(&ep->mtx);
        return -EINVAL;
    }

    switch (op) {
        case EPOLL_CTL_ADD:
            error = epoll_add(ep, fd, event);
            break;
        case EPOLL_CTL_DEL:
            error = epoll_remove(ep, fd);
            break;
        case EPOLL_CTL_MOD:
            error = epoll_modify(ep, fd, event);
            break;
        default:
            error = -EINVAL;
            break;
    }

    fput(f);
    fput(file);
    mutex_unlock(&ep->mtx);
    return error;
}

int epoll_ctl(int epfd, int op, int fd, struct epoll_event __user *event) {
    struct file *file, *ep_file;
    struct inode *inode, *ep_inode;
    int error;

    /* Check for invalid operation */
    if ((op != EPOLL_CTL_ADD) && (op != EPOLL_CTL_DEL) && (op != EPOLL_CTL_MOD))
        return -EINVAL;

    /* Retrieve file structures for epfd and fd */
    file = fget(fd);
    if (!file)
        return -EBADF;

    ep_file = fget(epfd);
    if (!ep_file) {
        fput(file);
        return -EBADF;
    }

    inode = file->f_inode;
    ep_inode = ep_file->f_inode;

    /* Ensure epfd is an epoll instance and not the same as fd */
    if (!S_ISCHR(inode->i_mode) || inode == ep_inode) {
        fput(file);
        fput(ep_file);
        return -EINVAL;
    }

    /* Acquire necessary locks to prevent race conditions */
    mutex_lock(&inode->i_mutex);

    /* Perform the requested operation (add, delete, modify) */
    if (op == EPOLL_CTL_ADD) {
        error = epoll_add(ep_inode, fd, event);
    } else if (op == EPOLL_CTL_DEL) {
        error = epoll_delete(ep_inode, fd);
    } else { /* EPOLL_CTL_MOD */
        error = epoll_modify(ep_inode, fd, event);
    }

    mutex_unlock(&inode->i_mutex);

    fput(file);
    fput(ep_file);

    return error;
}

#include <sys/epoll.h>
#include <linux/eventpoll.h>
#include <linux/fs.h>
#include <linux/uaccess.h>

int handle_epoll_ctl(int epfd, int op, int fd, struct epoll_event __user *event) {
    struct file *ep_file = fget(epfd);
    struct file *target_file = fget(fd);

    if (!ep_file || !target_file) {
        if (ep_file)
            fput(ep_file);
        if (target_file)
            fput(target_file);
        return -EBADF;
    }

    if (ep_file == target_file) {
        fput(ep_file);
        fput(target_file);
        return -EINVAL;
    }

    if ((op == EPOLL_CTL_ADD || op == EPOLL_CTL_MOD) && !target_file->f_op->poll) {
        fput(ep_file);
        fput(target_file);
        return -EINVAL;
    }

    struct epoll_event ep_event;
    if ((op == EPOLL_CTL_ADD || op == EPOLL_CTL_MOD) &&
        copy_from_user(&ep_event, event, sizeof(struct epoll_event))) {
        fput(ep_file);
        fput(target_file);
        return -EFAULT;
    }

    int result = -EINVAL;

    mutex_lock(&ep_file->f_lock);
    if (op == EPOLL_CTL_ADD) {
        // Perform addition logic
        result = do_epoll_ctl(epfd, op, fd, &ep_event);
    } else if (op == EPOLL_CTL_DEL) {
        // Perform deletion logic
        result = do_epoll_ctl(epfd, op, fd, NULL);
    } else if (op == EPOLL_CTL_MOD) {
        // Perform modification logic
        result = do_epoll_ctl(epfd, op, fd, &ep_event);
    }
    mutex_unlock(&ep_file->f_lock);

    fput(ep_file);
    fput(target_file);

    return (result < 0) ? result : 0;
}

int epoll_ctl(int epfd, int op, int fd, struct epoll_event __user *event) {
    struct file *file, *f;
    struct epoll *ep;
    int error;

    error = -EINVAL;
    if (op != EPOLL_CTL_ADD && op != EPOLL_CTL_DEL && op != EPOLL_CTL_MOD)
        return error;

    if ((file = fget(epfd)) == NULL)
        return -EBADF;

    if ((f = fget(fd)) == NULL) {
        fput(file);
        return -EBADF;
    }

    if (f == file) {
        fput(file);
        fput(f);
        return -EINVAL;
    }

    if (!f->f_op->poll) {
        fput(file);
        fput(f);
        return -EINVAL;
    }

    if (!(ep = file->private_data)) {
        fput(file);
        fput(f);
        return -EINVAL;
    }

    mutex_lock(&ep->lock);
    switch (op) {
        case EPOLL_CTL_ADD:
            error = do_epoll_add(ep, f, event);
            break;
        case EPOLL_CTL_DEL:
            error = do_epoll_del(ep, f);
            break;
        case EPOLL_CTL_MOD:
            error = do_epoll_mod(ep, f, event);
            break;
    }
    mutex_unlock(&ep->lock);

    fput(file);
    fput(f);
    return error;
}

#include <linux/eventpoll.h>
#include <linux/file.h>
#include <linux/fs.h>
#include <linux/uaccess.h>

int handle_epoll_ctl(int epfd, int op, int fd, struct epoll_event __user *event) {
    struct file *ep_file = fget(epfd);
    struct file *t_file = fget(fd);

    if (!ep_file || !t_file) {
        if (ep_file)
            fput(ep_file);
        if (t_file)
            fput(t_file);
        return -EBADF;
    }

    if (ep_file == t_file) {
        fput(ep_file);
        fput(t_file);
        return -EINVAL;
    }

    if (!(t_file->f_op && t_file->f_op->poll)) {
        fput(ep_file);
        fput(t_file);
        return -EINVAL;
    }

    struct epoll_event ep_event;
    if (copy_from_user(&ep_event, event, sizeof(struct epoll_event))) {
        fput(ep_file);
        fput(t_file);
        return -EFAULT;
    }

    int error = 0;

    mutex_lock(&ep_file->mutex);
    switch (op) {
        case EPOLL_CTL_ADD:
            error = do_epoll_ctl(ep_file, EPOLL_CTL_ADD, fd, &ep_event);
            break;
        case EPOLL_CTL_DEL:
            error = do_epoll_ctl(ep_file, EPOLL_CTL_DEL, fd, &ep_event);
            break;
        case EPOLL_CTL_MOD:
            error = do_epoll_ctl(ep_file, EPOLL_CTL_MOD, fd, &ep_event);
            break;
        default:
            error = -EINVAL;
    }
    mutex_unlock(&ep_file->mutex);

    fput(ep_file);
    fput(t_file);
    return error;
}
